from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = list(map(int, lines[1].split()))
    m = int(lines[2])

    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        action = parts[0]
        team = int(parts[1])
        actions.append((action, team))

    # Sort heroes by strength descending
    strengths.sort(reverse=True)

    # DP state: (used_mask, action_idx) -> result
    # used_mask: bitmask of already used heroes
    @lru_cache(maxsize=None)
    def dp(used_mask, action_idx):
        if action_idx == m:
            return 0

        action_type, team = actions[action_idx]

        if action_type == 'p':
            # Pick: find and use the strongest available hero
            # Add to Team 1's score (+), subtract from difference if Team 2 picks (-)
            for idx in range(len(strengths) - 1, -1, -1):
                if not (used_mask & (1 << idx)):
                    val = strengths[idx]
                    # Team 1 pick: adds val to their score (+val)
                    # Team 2 pick: adds val to theirs (-val to difference)
                    return ((1 if team == 1 else -1) * val) + dp(used_mask | (1 << idx), action_idx + 1)
        else:  # 'b'
            # Ban: find and remove the strongest available hero (no immediate points change)
            for idx in range(len(strengths) - 1, -1, -1):
                if not (used_mask & (1 << idx)):
                    return dp(used_mask | (1 << idx), action_idx + 1)

    initial_mask = 0
    result = dp(initial_mask, 0)
    return f"{result}\n"

