def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return "YES\n\n"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "YES\n\n"

    if n == 0:
        return "YES\n\n"

    edges = []
    for i in range(1, min(len(lines), m + 1)):
        parts = lines[i].split()
        if len(parts) >= 3:
            a, b, c = int(parts[0]), int(parts[1]), int(parts[2])
            # Convert to 0-indexed
            edges.append((a - 1, b - 1, c))

    if not edges:
        return f"YES\n{' '.join(['0'] * n)}\n"

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, c in edges:
        adj[a].append((b, c))
        adj[b].append((a, c))

    # Track which nodes have been assigned values
    assigned = [-1] * n

    # Process each connected component
    for start in range(n):
        if assigned[start] != -1:
            continue

        # BFS to traverse the component
        visited = [False] * n
        rel_to_root = {}  # node -> value when root = 0

        queue = [start]
        visited[start] = True
        rel_to_root[start] = 0.0
        component_nodes = [start]

        consistent = True

        while queue:
            u = queue.pop(0)

            for v, c in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    rel_to_root[v] = c - rel_to_root[u]
                    component_nodes.append(v)
                    queue.append(v)
                else:
                    # Check for cycle consistency
                    expected_v = c - rel_to_root[u]
                    if abs(rel_to_root[v] - expected_v) > 1e-9:
                        consistent = False
                        break
            if not consistent:
                break

        if not consistent:
            return "NO"

        # Find all edge constraints involving nodes in this component
        r_candidates = []
        for a, b, c in edges:
            if a in rel_to_root and b in rel_to_root:
                # (rel_a + r) + (rel_b + r) = c
                # 2*r = c - rel_a - rel_b
                r = (c - rel_to_root[a] - rel_to_root[b]) / 2.0
                r_candidates.append(r)

        # For L1 minimization, use the median
        if r_candidates:
            r_candidates.sort()
            r = r_candidates[len(r_candidates) // 2]
        else:
            r = 0.0

        # Assign values to all nodes in this component
        for node in component_nodes:
            if node in rel_to_root:
                x = rel_to_root[node] + r
                assigned[node] = x

    # Check if all nodes are assigned
    if -1 in assigned:
        return "NO"

    # Verify all constraints
    for a, b, c in edges:
        x_a = assigned[a]
        x_b = assigned[b]
        if abs(x_a + x_b - c) > 1e-6:
            return "NO"

    # Output
    output_values = []
    for i in range(n):
        if i > 0:
            output_values.append(' ')
        output_values.append(f"{assigned[i]:.6f}")

    return f"YES\n{''.join(output_values)}\n"


