import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ""

    edges = []
    for i in range(m):
        parts = lines[i+1].split()
        edges.append((int(parts[0])-1, int(parts[1])-1, int(parts[2]), i))

    # Sort by weight for Kruskal's
    edges.sort(key=lambda x: x[2])

    # Union-Find for Kruskal's
    uf = list(range(n))
    def find(x):
        root = x
        while uf[root] != root:
            root = uf[root]
        return root
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            uf[rx] = ry
            return True
        return False

    # Build MST
    in_mst = [False] * m
    adj = [[] for _ in range(n)]

    for u, v, w, i in edges:
        if union(u, v):
            in_mst[i] = True
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Build LCA and path max tables using DFS
    depth = [-1] * n
    parents = [-1] * n

    # Iterative DFS from node 0
    stack = [(0, -1, 0)]
    while stack:
        u, p, d = stack.pop()
        depth[u] = d
        parents[u] = p
        for v, _ in adj[u]:
            if v != p:
                stack.append((v, u, d + 1))

    # Binary lifting tables
    K = 20  # Sufficient since 2^20 > 10^5
    parent_table = [[0]*n for _ in range(K)]
    max_table = [[0]*n for _ in range(K)]

    for i in range(n):
        parent_table[0][i] = parents[i]
        max_table[0][i] = 0  # Will be set during traversal

    def build_tables():
        # Re-run DFS to properly set ancestors and compute max edges
        depth = [-1] * n
        parents = [-1] * n

        stack = [(0, -1, 0)]
        order = []
        while stack:
            u, p, d = stack.pop()
            depth[u] = d
            parents[u] = p
            order.append(u)
            for v, w in adj[u]:
                if v != p:
                    stack.append((v, u, d + 1))

        # Build tables in increasing order of power
        for i in range(1, K):
            for u in range(n):
                mid = parent_table[i-1][u]
                parent_table[i][u] = parent_table[i-1][mid]
                a1 = max_table[i-1][u]
                a2 = max_table[i-1][mid]
                max_table[i][u] = a1 if a1 > a2 else a2

    build_tables()

    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        for i in range(K-1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                u = parent_table[i][u]

        if u == v:
            return u

        for i in range(K-1, -1, -1):
            if parent_table[i][u] != parent_table[i][v]:
                u = parent_table[i][u]
                v = parent_table[i][v]

        return parent_table[0][u]

    def path_max(u, v):
        lca = get_lca(u, v)
        ans = 0
        du, dv = depth[u], depth[v]

        # Lift u to lca depth
        for i in range(K-1, -1, -1):
            d_desc = du - (1 << i)
            if d_desc >= depth[lca]:
                ans = max(ans, max_table[i][u])
                u = parent_table[i][u]
                du = d_desc

        # Lift v to lca depth  
        for i in range(K-1, -1, -1):
            d_desc = dv - (1 << i)
            if d_desc >= depth[lca]:
                ans = max(ans, max_table[i][v])
                v = parent_table[i][v]
                dv = d_desc

        # Lift both to lca (same depth now)
        for i in range(K-1, -1, -1):
            if parent_table[i][u] != parent_table[i][v]:
                ans = max(ans, max_table[i][u], max_table[i][v])
                u = parent_table[i][u]
                v = parent_table[i][v]

        return ans

    # Build reverse order of edges for output
    output = []
    for i in range(m-1, -1, -1):
        # Find original weight of edge i
        orig_weight = 0
        for u, v, w, idx in edges:
            if idx == i:
                orig_weight = w
                break

        if not in_mst[i]:
            # Original indices matter for output order
            # Rebuild output in correct order
            pass

    # Output in original edge order (skip MST edges)
    output = []
    for u, v, w, i in edges:
        if not in_mst[i]:
            max_val = path_max(u, v)
            output.append(max_val)

    # But we need to output in input order, not sorted order
    # Re-process with original edge info
    output = []
    for i in range(m):
        # Find edge i
        for u, v, w, idx in edges:
            if idx == i:
                if not in_mst[i]:
                    output.append(str(path_max(u, v)))
                break

    return "\n".join(output)

