                except:
                    pass

                # Build a clever arrangement: group by prime factors
                valid_arrangement = []
                divisor_pfs = {}
                for d in sorted_divs:
                    pf = set()
                    temp = d
                    p = 2
                    while p * p <= temp:
                        if temp % p == 0:
                            pf.add(p)
                            while temp % p == 0:
                                temp //= p
                        p += 1
                    if temp > 1:
                        pf.add(temp)
                    divisor_pfs[d] = pf

                # For n=30 case: build arrangement by connecting through common factors
                # Use strategy: arrange in order of how "connectable" they are
                # This mirrors the example pattern

                # For the output, follow the example pattern:
