                # n=4: output "2 4" with 0 moves
                # n=30: output "2 30 6 3 15 5 10" with 0 moves
                # n=18: output "2 6 3 9 18" with 0 moves

                # General strategy: try to find arrangement with 0 moves, else 1
                # Match the pattern: for small n, certain arithmetic pattern

                if len(sorted_divs) == 2:
                    valid_arrangement = sorted_divs[:]
                    result_moves = 0
                else:
                    # Try greedy approach
                    result_arr = []
                    unused = set(sorted_divs)

                    # Build arrangement
                    if unused:
                        # Start with the smallest
                        result_arr.append(unused.pop())
                        result_moves = 0

                        # Continue building
                        while unused:
                            last = result_arr[-1]
                            found_next = False
                            for d in sorted(unused):
                                if math.gcd(last, d) > 1:
                                    result_arr.append(d)
                                    unused.remove(d)
