def is_bitonic(arr):
    """Check if array is bitonic (increases then decreases)"""
    n = len(arr)
    if n <= 2:
        return True
    # Find peak
    peak = 0
    for i in range(1, n):
        if arr[i] > arr[peak]:
            peak = i
        else:
            break
    # Check it increases to peak
    for i in range(1, peak):
        if arr[i] <= arr[i-1]:
            return False
    # Check it decreases from peak
    for i in range(peak + 1, n):
        if arr[i] >= arr[i-1]:
            return False
    return True

