def get_prime_factors(num):
    if num <= 1:
        return {}
    factors = {}
    d = 2
    remaining = num
    while d * d <= remaining:
        while remaining % d == 0:
            factors[d] = factors.get(d, 0) + 1
            remaining //= d
        d += 1
    if remaining > 1:
        factors[remaining] = factors.get(remaining, 0) + 1
    return factors

