            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                edges.append((u, v))

    if m == 0:
        # No edges, only isolated vertices - |n-1| merges to connect
        return str(max(0, n - 1)) + '\n'

    # Build adjacency list
    adj = {i: set() for i in range(1, n + 1)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Find connected components and check properties
    visited = {i: False for i in range(1, n + 1)}
    processing = []

    def dfs(u, component_nodes, has_cycle, has_degree_gt_2):
        visited[u] = True
        component_nodes.add(u)

        for v in adj[u]:
            if not visited[v]:
                dfs(v, component_nodes, has_cycle, has_degree_gt_2)
            elif v in visited[u]:
                has_cycle = True

        has_degree_gt_2 |= False  # Will check degrees instead

    components = []
    for i in range(1, n + 1):
        if not visited[i]:
            component_nodes = set()
            has_cycle = False
            degrees = defaultdict(list)

            # BFS from i
            stack = [i]
            component_visited = {i}

            while stack:
                u = stack.pop()
                component_nodes.add(u)
                degrees[u] = len(adj[u])

                if degrees[u] > 2:
                    has_degree_gt_2 = True

                for v in adj[u]:
                    if v not in component_visited:
                        component_visited.add(v)
                        stack.append(v)

            # To detect cycle in DFS
            stack = [i]
            parent = {i: None}
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if v == parent[u]:
                        continue
                    if v in component_visited:
                        has_cycle = True
                    else:
                        stack.append(v)
                        component_visited.add(v)
                        parent[v] = u

            if n_i := len(component_nodes) > 0:
                # Count edges within component
                comp_edges = sum(len(adj[u]) for u in component_nodes) // 2

                # Calculate penalty
                if has_cycle and comp_edges > n_i - 1:
                    penalty = 2
                elif has_degree_gt_2 or comp_edges != n_i - 1:
                    penalty = 1
                else:
                    penalty = 0

                components.append(penalty)

    ans = len(components) - 1 + sum(components)

    return str(ans) + '\n'


