def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])
    patterns = []
    for i in range(1, min(m + 1, len(lines))):
        patterns.append(lines[i])
    MOD = 1000000009

    if n == 0:
        return '0\n'

    # Build Aho-Corasick automaton
    trie = [{}]  # trie[u] is dict mapping char -> next_node
    fail = [0]   # fail[u] is failure link for node u
    end = [0]    # end[u] = 1 if node u is end of some pattern
    node_cnt = 1

    # Insert patterns into trie
    for pat in patterns:
        u = 0
        for c in pat:
            if c not in trie[u]:
                trie[u][c] = node_cnt
                trie.append({})
                end.append(0)
                fail.append(0)
                node_cnt += 1
            u = trie[u][c]
        end[u] = 1

    # Build failure links using BFS
    from collections import deque
    q = deque([0])
    while q:
        u = q.popleft()
        for c, v in trie[u].items():
            f = fail[u]
            while f != 0 and c not in trie[f]:
                f = fail[f]
            fail[v] = trie[f].get(c, 0) if f != 0 else 0
            end[v] = max(end[v], end[fail[v]])
            q.append(v)

    # DP: dp[u] = number of valid strings of current length ending at trie node u
    dp = [1] + [0] * (node_cnt - 1)

    for _ in range(n):
        new_dp = [0] * node_cnt
        for u in range(node_cnt):
            if dp[u] == 0:
                continue

            for c in 'ACGT':
                # Find next state for char c
                if c in trie[u]:
                    v = trie[u][c]
                else:
                    f = fail[u]
                    while f != 0 and c not in trie[f]:
                        f = fail[f]
                    v = trie[f].get(c, 0) if f != 0 else 0

                # Check if position is covered by checking if any pattern ends 
                # at current node or reachable via failure links
                temp = v
                covered = False
                while temp != 0:
                    if end[temp]:
                        covered = True
                        break
                    temp = fail[temp]

                if covered:
                    new_dp[v] = (new_dp[v] + dp[u]) % MOD

        dp = new_dp

    return str(sum(dp) % MOD) + '\n'

