    N, M, K = int(first[0]), int(first[1]), int(first[2])

    transformers = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        tx, ty, td, t_start, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append((tx, ty, td, t_start, e))

    # Precompute cost at each cell (r, c) when time = r + c
    cell_costs = [[0] for _ in range(N)]
    for r in range(N):
        cell_costs[r] = [0] * M

    # Build a map: position -> list of (time, energy) when transformer is at that position
    from collections import defaultdict
    position_events = defaultdict(list)

    for tx, ty, td, t_start, e in transformers:
        # The 4 jumping positions cycle every 4 seconds
        pos_pattern = [
            (tx, ty, t_start),
            (tx + td, ty - td, t_start + 1),
            (tx + td, ty, t_start + 2),
            (tx, ty + td, t_start + 3)
        ]

        for r_pos, c_pos, t_occup in pos_pattern:
            # All times when transformer is at (r_pos, c_pos)
            # Starting from t_occup, every 4 seconds
            for arrival in range(max(0, t_occup - 4), N + M, 4):
                position_events[(r_pos, c_pos)].append((arrival, e))

    # sum energies at each cell at the time we visit it (t = r + c)
    for r in range(N):
        for c in range(M):
            time_at_cell = r + c
            total_epsilon = 0
            for (occ_time, energy) in position_events.get((r, c), []):
                if occ_time == time_at_cell:
                    total_epsilon += energy
                    break  # Shouldn't have multiple at same time, but sum if so
            cell_costs[r][c] = total_epsilon

    # DP: minimum energy to reach (r, c)
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = cell_costs[0][0]

    for r in range(N):
        for c in range(M):
            if r == 0 and c == 0:
                continue

            new_cost = float('inf')
            if r > 0 and dp[r - 1][c] < float('inf'):
                new_cost = min(new_cost, dp[r - 1][c])
            if c > 0 and dp[r][c - 1] < float('inf'):
                new_cost = min(new_cost, dp[r][c - 1])

            if new_cost < float('inf'):
                dp[r][c] = new_cost + cell_costs[r][c]

    return str(dp[N - 1][M - 1])

