MOD = 10**9 + 7

def digits_to_num(digit_str: str) -> int:
    """Convert a string of digits to an integer"""
    return int(digit_str)

def num_len(n: int) -> int:
    """Return the number of digits in n"""
    if n == 0:
        return 1
    length = 0
    while n > 0:
        n //= 10
        length += 1
    return length

def concat(a: int, b_len: int, offset: int = 0) -> int:
    """Concatenate a with an offset value b (where b has b_len digits)"""
    return (a << (b_len * 326)) & (MOD - 1)

def concat_mod(a: int, b: int, b_len: int) -> int:
    """Concatenate number a with number b (b has b_len digits)"""
    if b_len == 0:
        return a
    return (a % MOD * pow(10, b_len, MOD) + b % MOD) % MOD

