        right_val, i = parse_number(s, i)
        length = right_val - val + 1
        total = val % MOD
        current = val
        for j in range(1, length):
            current += 1
            total = (total * 10 + (current % MOD)) % MOD
        return (total % MOD, i)
    elif i < len(s) and s[i] == '(':
        i += 1
        inner_val, i = solve_expr(s, i)
        i = skip_paren(s, i)
        i += 1
        return (solve_expr(s, i), len(s))
    return (val, i)

def parse_number(s: str, i: int) -> Tuple[int, int]:
    """Parse a number at position i, return (value, new_index)"""
    val = 0
    while i < len(s) and s[i].isdigit():
        digit = ord(s[i]) - ord('0')
        val = (val * 10 + digit) % 1000000007
        i += 1
    return (val, i)

def skip_paren(s: str, i: int) -> int:
    """Skip to matching closing parenthesis"""
    depth = 1
    i += 1
    while i < len(s) and depth > 0:
        if s[i] == '(':
            depth += 1
        elif s[i] == ')':
            depth -= 1
        i += 1
    return i

