import sys
from itertools import product

def rev(x):
    rev_x = int(str(x)[::-1])
    return rev_x

def count_lucky(max_a, max_b, lucky_tickets):
    count = 0
    for a in range(1, max_a + 1):
        for b in range(1, max_b + 1):
            if (a, b) in lucky_tickets:
                count += 1
    return count

def solution(input_string):
    parts = input_string.strip().split()
    maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])

    # Precompute lucky tickets up to maxx and maxy
    lucky_tickets = set()
    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            if a * b == rev(a) * rev(b):
                lucky_tickets.add((a, b))

    # Search for minimum x * y that satisfies the constraint
    ans = None
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            count = count_lucky(x, y, lucky_tickets)
            if count >= w and ans is None:
                if ans is None or x * y < ans or (x * y == ans and x <= ans_x and y <= ans_y):
                    ans = x * y
                    ans_x, ans_y = x, y

    if ans is None:
        return '-1'
    else:
        return ans_x

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k, m = map(int, lines[0].split())
    MOD = 10**9 + 7

    if k == 1:
        # Just choose any starting planet
        return str(n % MOD)

    if k == 2:
        # Count valid 2-planet sequences
        # For starting position s: valid destinations are in [1, s+m] excluding s
        # Memoization on (n, s, m) pattern yields closed form
        if n - m <= 0:  # m >= n, then all planets reachable from any start except itself
            return str((n * (n - 1)) % MOD)
        # Transition point: for s <= n-m, count = s+m-1
        # For s > n-m, count = n-1 (boundary)
        term1 = (n - m) * (n + m - 1) // 2
        term2 = m * (n - 1)
        return str((term1 + term2) % MOD)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(current, length, visited):
        """Count valid sequences of remaining length starting from current planet,
        with given visited planets. Visited is a sorted tuple of unsorted values."""
        if length == 0:
            return 1

        total = 0
        max_reach = min(n, current + m)
        visited_set = set(visited)

        for next_p in range(1, max_reach + 1):
            if next_p not in visited_set:
                new_visited = visited + (next_p,)
                new_visited = tuple(sorted(new_visited))
                total = (total + dp(next_p, length - 1, new_visited)) % MOD

        return total

    total = 0
    for start in range(1, n + 1):
        total = (total + dp(start, k - 1, (start,))) % MOD

    return str(total)
